{"path": "src/riskscore/velocity.py", "content": """"How fast a sku has been selling, once short-run noise is smoothed out.
"""
import numpy as np
import pandas as pd

WINDOW = 10


def sku_velocity(fit_df):
    days = fit_df["placed_at"].dt.normalize()
    daily = fit_df.groupby([fit_df["sku"], days])["units"].sum()
    out = {}
    for sku, series in daily.groupby(level=0):
        series = series.droplevel(0)
        full = series.reindex(
            pd.date_range(series.index.min(), series.index.max()), fill_value=0.0)
        smoothed = full.rolling(WINDOW).mean().dropna()
        if len(smoothed):
            out[sku] = float(smoothed.mean())
    return pd.Series(out, dtype="float64")


def add(df, velocity):
    out = df.copy()
    portfolio = float(velocity.mean())
    out["f_sku_velocity"] = out["sku"].map(velocity).fillna(portfolio)
    return out
